import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.YiAtXB4p.js";const m=JSON.parse('{"title":"Client architecture","description":"","frontmatter":{"title":"Client architecture","sourceFile":"guides/CLIENT-ARCHITECTURE.md"},"headers":[],"relativePath":"guide/client-architecture.md","filePath":"guide/client-architecture.md"}'),c={name:"guide/client-architecture.md"};function n(r,e,i,s,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="client-architecture" tabindex="-1">Client architecture <a class="header-anchor" href="#client-architecture" aria-label="Permalink to &quot;Client architecture&quot;">​</a></h1><p><strong>Implements:</strong> posture 1, <code>ARCH-14</code> and <code>ARCH-08</code> · see <a href="./charter">CHARTER.md</a> Parts 1 and 2. <strong>Checked by:</strong> <code>tests/tdd/scripts/custom-client-identity.test.ts</code>. <strong>Decided:</strong> 2026-10-17 in <a href="https://github.com/lgriffin/ESI.ts/issues/664" target="_blank" rel="noreferrer">#664</a>, option D.</p><p>ESI.ts is a library of hand-written, curated custom clients. The code that is generated from the ESI OpenAPI document is the foundation underneath them, not a replacement for them. This page records that decision and the plan that follows from it.</p><hr><h2 id="the-decision" tabindex="-1">The decision <a class="header-anchor" href="#the-decision" aria-label="Permalink to &quot;The decision&quot;">​</a></h2><blockquote><p>&quot;D please. The core identity of the project is the custom approach and we should never give that up. This needs enshrined in the charter&quot; (the maintainer, on #664)</p></blockquote><ul><li><strong>The custom clients are the product.</strong> <code>EsiClient</code>, <code>EsiClientBuilder</code> → <code>CustomEsiClient</code>, <code>EsiApiFactory.createClient(type)</code> and the 39 domain clients in <code>src/clients/</code>, over the endpoint maps in <code>src/core/endpoints/</code> and the Zod schemas in <code>src/schemas/</code>. Method names, argument order, body builders, wire fixes and validation strictness are product decisions, made by people.</li><li><strong>Generation serves them.</strong> The generated operations (<code>src/generated/operations.generated.ts</code>) and their <code>*Meta</code> supply paths, scopes, schemas and coverage. They never replace a custom client.</li><li><strong><code>createEsi()</code> from <code>@lgriffin/esi.ts/client</code> is the spec-shaped low-level surface.</strong> It stays documented for anyone who wants calls that mirror the URL and the spec&#39;s parameters exactly (<code>esi.public</code>, <code>esi.as(identity)</code>, <a href="./multi-character">MULTI-CHARACTER.md</a>), and it becomes the engine under the custom clients. It needs no feature parity with them.</li><li><strong>Changing this is a charter amendment first.</strong> ARCH-14 fails a change that deprecates or removes a custom-client construction surface, or replaces one with the generated surface.</li></ul><h3 id="what-1220-changes" tabindex="-1">What 12.2.0 changes <a class="header-anchor" href="#what-1220-changes" aria-label="Permalink to &quot;What 12.2.0 changes&quot;">​</a></h3><p>12.1.0 marked the custom clients <code>@deprecated</code> for removal in 13.0.0, following a plan to make <code>createEsi()</code> the only surface. 12.2.0 lifts those deprecations. That is a compatible change: no name, signature or behaviour changes.</p><table tabindex="0"><thead><tr><th>Surface</th><th>12.1.0</th><th>12.2.0</th></tr></thead><tbody><tr><td><code>EsiClient</code>, <code>getDefaultClient</code>, <code>EsiClientBuilder</code>, <code>CustomEsiClient</code></td><td>Deprecated, removed in 13.0.0</td><td>Supported</td></tr><tr><td><code>EsiApiFactory</code> and <code>EsiApiFactory.createClient(type)</code></td><td>Deprecated, removed in 13.0.0</td><td>Supported</td></tr><tr><td><code>EsiApiFactory</code>&#39;s nine named factories (<code>createMarketClient</code> and the rest)</td><td>Deprecated since 11.0.0</td><td>Still deprecated, in favour of <code>createClient(type)</code> or <code>EsiClientBuilder</code> (<code>createEsi()</code> as the spec-shaped alternative). Removal needs a future major release; none is scheduled.</td></tr><tr><td><code>EsiTokenManager.createClient</code></td><td>Deprecated since 11.0.0</td><td>Still deprecated, in favour of <code>esi.as(tokens.identity(id))</code>. Removal needs a future major release; none is scheduled.</td></tr><tr><td><code>BaseEsiClient</code>, the 39 domain clients, <code>ApiClientType</code>, <code>RouteOptions</code>, <code>ApiClientBuilder</code></td><td>Deprecated, removed in 13.0.0</td><td>Supported</td></tr><tr><td><code>ApiClient</code>, <code>configureApiClient</code>, the page, cursor and batch helpers, diagnostics, and 25 in all</td><td>Deprecated re-exports</td><td>Exported from their declarations again; every name and type unchanged</td></tr><tr><td>The 194 hand-written response types in <code>src/types</code>, <code>TestDataFactory</code>, the <code>./schemas</code> entry</td><td>Deprecated, removed in 13.0.0</td><td>Supported</td></tr><tr><td><code>DeprecationInfo</code> on endpoint definitions</td><td>Unchanged: per-call warnings from ESI</td><td>Unchanged</td></tr></tbody></table><p>No 13.0 is planned.</p><hr><h2 id="the-plan" tabindex="-1">The plan <a class="header-anchor" href="#the-plan" aria-label="Permalink to &quot;The plan&quot;">​</a></h2><p>Each step is additive or internal, so each can ship in a 12.x minor release. A future major would only be for clean-up chosen later, such as dropping setters that identity views make redundant.</p><ol><li><strong>Lift the deprecations</strong> (12.2.0, this page). Posture 1 and ARCH-14 go into the charter.</li><li><strong>Derive the endpoint maps from the generated <code>*Meta</code>.</strong> Path, method, scopes, pagination kind and headers come from the spec. The hand-written part shrinks to what a custom client adds: the method name, argument order, <code>bodyBuilder</code>, and the wire fixes the spec gets wrong (query versus body for <code>addContacts</code>, comma-joined ids, <code>read</code> rather than <code>is_read</code>), kept in one overlay. <code>spec:coverage</code> then also proves every custom method points at a real operation. A spike on two domains comes before converting all 39.</li><li><strong>Generate the baseline schemas, hand-write the overrides.</strong> The generated response schemas become the baseline, and a hand-written schema stays only where ESI&#39;s wire differs from the spec. Schema drift becomes a generator diff instead of an audit.</li><li><strong>Identity views for the custom clients.</strong> A shared runtime with per-identity views, along the lines of <code>client.as(identity)</code> returning the same custom clients bound to one character over one cache, rate-limit budget and breaker, and a public-only builder whose types omit authenticated methods. Custom-client users get the multi-character model without learning a new call style.</li><li><strong>Close runtime gaps once, in the shared runtime.</strong> Parallel page collection, response metadata and safe mode, diagnostics, swappable middleware and nameable response types are built where both surfaces see them, not twice. <ul><li><strong>Response metadata and safe mode</strong> (12.x): one reader, <code>buildResponseMeta</code> in <code>src/core/responseMeta.ts</code>, serves each domain client&#39;s <code>withMetadata()</code>, the new <code>EsiClient.withMetadata()</code> / <code>withSafeMode()</code> and <code>CustomEsiClient.withMetadata()</code> / <code>withSafeMode()</code> (every domain from one call), and <code>esi.withMetadata()</code> / <code>esi.withSafeMode()</code>.</li><li><strong>Diagnostics</strong> (12.x): <code>EsiDiagnostics</code> backs <code>EsiClient.diagnostics</code>, the new <code>CustomEsiClient.diagnostics</code> and its shortcuts, and <code>esi.diagnostics</code>.</li><li><strong>Swappable middleware</strong> (12.x): <code>cache</code>, <code>rateLimiter</code>, <code>circuitBreaker</code>, <code>deduplicator</code> and <code>clock</code> are <code>EsiClientConfig</code> fields that <code>configureApiClient</code> installs, so <code>EsiClient</code>, the builder, <code>EsiApiFactory.createClient</code> and <code>createEsi</code> (whose <code>EsiOptions</code> carry the same five) take them the same way.</li></ul></li></ol><h3 id="shared-already" tabindex="-1">Shared already <a class="header-anchor" href="#shared-already" aria-label="Permalink to &quot;Shared already&quot;">​</a></h3><p>A feature the generated layer gains reaches the custom clients through the same pipeline code, not a copy of it:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Custom clients</th><th><code>createEsi()</code></th><th>One implementation</th></tr></thead><tbody><tr><td>Deprecation warnings</td><td><code>DeprecationInfo</code> on the endpoint definition: <code>Endpoint &#39;&lt;method&gt;&#39; is deprecated. …</code></td><td><code>OperationMeta.deprecation</code>: <code>Operation &#39;&lt;operationId&gt;&#39; is deprecated. …</code></td><td><code>src/core/endpoints/deprecationWarning.ts</code></td></tr><tr><td>The OpenAPI document, as JSON and YAML</td><td><code>meta.getOpenApiJson()</code>, <code>meta.getOpenApiYaml()</code></td><td><code>meta.openapiJson.get()</code>, <code>meta.openapiYaml.get()</code></td><td><code>textResponse</code> through <code>handleRequest</code>; the same Accept header and the same JSON schema</td></tr><tr><td>An empty answer on a public contract</td><td><code>getPublicContractBids/Items</code>, <code>fetchAllPublicContractBids/Items</code>, <code>streamPublicContractBids/Items</code>, and <code>streamEndpoint</code>/<code>fetchAllEndpoint</code> by name</td><td><code>contracts.public.bids(id).get()</code>, <code>contracts.public.items(id).get()</code></td><td><code>answeredWithNoContent</code> and <code>emptyListWhenNoContent</code> in <code>src/core/requestPipeline/statusHandling.ts</code></td></tr></tbody></table><p>The endpoint maps stay hand-written and <code>src/core</code> may not import the generated layer, so <code>tests/tdd/core/endpointOperationParity.test.ts</code> holds the two in step: it fails when an endpoint definition and its generated operation disagree about deprecation (with the message and sunset date from <code>scripts/spec/operation-overlay.json</code>), a text response and its Accept header, or reading no content as an empty list. Step 2 of the plan derives these facts instead of checking them.</p><hr><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Where</th><th>Role</th></tr></thead><tbody><tr><td>Custom clients</td><td><code>src/EsiClient.ts</code>, <code>src/EsiClientBuilder.ts</code>, <code>src/clients/</code></td><td>The product: named methods, curated arguments, helpers</td></tr><tr><td>Endpoint maps, schemas</td><td><code>src/core/endpoints/*Endpoints.ts</code>, <code>src/schemas/</code></td><td>What each method calls and how its answer is validated</td></tr><tr><td>Request pipeline</td><td><code>src/core/</code></td><td>Cache, retry, rate limiter, breaker, deduplicator, pagination; shared</td></tr><tr><td>Generated operations</td><td><code>src/generated/</code>, <code>src/adapters/</code></td><td>One typed function and <code>*Meta</code> per spec operation; the foundation</td></tr><tr><td>Spec-shaped surface</td><td><code>src/client/</code> (<code>./client</code>)</td><td><code>createEsi()</code>, <code>esi.public</code>, <code>esi.as(identity)</code> over the generated layer</td></tr></tbody></table><p><a href="./architecture">ARCHITECTURE.md</a> walks a request through the pipeline, and <a href="./semver">SEMVER.md</a> says how each kind of change is released.</p>',23)])])}const u=t(c,[["render",n]]);export{m as __pageData,u as default};
